n_opencode_Adapter_Reconcile.signature:
// Reconcile 把断连期间错过的回合终态补回事件流。
//
// 参数：
//   - ctx: 控制查询超时
//   - taskID: 目标任务；运行态不在（未 Start / 已 Stop）时返回「无运行态」结论而非错误
//
// 返回：
//   - ReconcileOutcome: 结论。Emitted 只可能是 0 或 1（spec §2.2 的不变量）；
//     Pending 恒为 0（见文件头注释）
//   - err: 查会话失败。**调用方收到错误时只记 WARN、不改任何状态**——一次网络
//     抖动不该把能恢复的任务判成不可恢复
//
// 注意：
//   - 是否补发由 WatermarkArmed 决定（见 proc.go 的 armed 语义）：未 armed 的
//     legacy 会话**不补发**，只把当前尾部认作已消费基线——否则升级到本版本的
//     存量任务会在第一次恢复时集体重放最后一个回合；armed 会话空水位即「第一个
//     回合尚未消费」，必须补发（B38 头号场景）
//   - 「补发 → 前进水位」在 turnMu 下串行完成，与实时路径的 mapIdle 互斥；
//     拆成两步会让两条路同时判「未消费」而补出两条终态
func (a *Adapter) Reconcile(ctx context.Context, taskID string) (executor.ReconcileOutcome, error) {
	a.log.Info("adapter 开始对账", "task", taskID)

	a.mu.Lock()
	r := a.runs[taskID]
	a.mu.Unlock()
	if r == nil || r.api == nil {
		a.log.Info("对账跳过：该任务无运行态", "task", taskID)
		return executor.ReconcileOutcome{Note: "该任务当前无运行态，无需对账"}, nil
	}

	msg, err := r.api.LastAssistantMessage(ctx, r.session)
	if err != nil {
		a.log.Warn("对账查会话尾部失败，不改任何状态", "task", taskID, "cause", err)
		return executor.ReconcileOutcome{Note: "查会话尾部失败"},
			fmt.Errorf("对账查会话尾部: %w", err)
	}
	if msg == nil {
		a.log.Info("对账结论：会话尚无 assistant 消息", "task", taskID)
		return executor.ReconcileOutcome{Note: "会话里还没有模型消息，无需对账"}, nil
	}
	ended, reason := reconcileTurnEnded(msg)
	if !ended {
		a.log.Info("对账结论：回合仍在进行，不补发",
			"task", taskID, "msg", msg.ID, "reason", reason)
		return executor.ReconcileOutcome{Note: "executor 的回合仍在进行中，没有丢失的终态"}, nil
	}

	r.turnMu.Lock()
	defer r.turnMu.Unlock()

	pi, err := readProcInfo(r.taskDir)
	if err != nil {
		a.log.Warn("对账读凭据失败，不改任何状态", "task", taskID, "cause", err)
		return executor.ReconcileOutcome{Note: "读恢复凭据失败"},
			fmt.Errorf("对账读恢复凭据: %w", err)
	}
	if pi.LastTurnMsgID == msg.ID {
		a.log.Info("对账结论：终态已送达过，无需补发", "task", taskID, "msg", msg.ID)
		return executor.ReconcileOutcome{TurnEnded: true,
			Note:	"回合已完结，且终态此前已送达，无需补发"}, nil
	}
	if !pi.WatermarkArmed {

		pi.LastTurnMsgID = msg.ID
		if werr := writeProcInfo(r.taskDir, pi); werr != nil {
			a.log.Warn("首次对账写水位失败", "task", taskID, "cause", werr)
		}
		a.log.Info("对账结论：未 armed 认基线，已把当前会话尾部记为基线，不补发",
			"task", taskID, "msg", msg.ID, "armed", false)
		return executor.ReconcileOutcome{TurnEnded: true,
			Note:	"会话非本版本新建（legacy），已把当前进度记为基线（不回溯此前的回合）"}, nil
	}

	ev, note := a.classifyReconciled(r, msg)
	if !a.emit(r, ev) {
		a.log.Warn("对账补发失败：事件通道已关闭", "task", taskID, "msg", msg.ID)
		return executor.ReconcileOutcome{TurnEnded: true,
			Note:	"回合已完结但事件通道已关闭，未能补发"}, nil
	}
	pi.LastTurnMsgID = msg.ID
	if werr := writeProcInfo(r.taskDir, pi); werr != nil {
		a.log.Warn("对账后写水位失败，下次对账可能重复补发",
			"task", taskID, "msg", msg.ID, "cause", werr)
	}
	a.log.Info("对账完成：已补发断连期间丢失的终态",
		"task", taskID, "msg", msg.ID, "event", ev.Type, "note", note, "armed", true)
	return executor.ReconcileOutcome{TurnEnded: true, Emitted: 1, Note: note}, nil
}

n_opencode_Adapter_Resume.signature:
// Resume 重建 agentd 重启前已在执行的任务（spec §8「存活则重连 SSE 继续」）：
// 从任务目录的 proc.json 恢复 serve 连接凭据并探活（存活锁 + HTTP 应答）；
// 存活则重建 SSE 订阅、看门狗与事件通道，返回 Reattach。
//
// 参数：
//   - req: 恢复请求（TaskDir 是 proc.json 所在，即 DataDir/tasks/<id>；
//     RepoPath 用于重启后重新捕获 git 兜底分类的起点 commit 基线；
//     SessionID 是落库的 opencode 会话 id）
//
// 返回：
//   - Alive=false 时调用方（manager）把任务转 failed 交协调者裁决（保守优于静默）
//   - err: 重建失败（proc.json 缺失/损坏、SessionID 为空），此时视为不可恢复
//
// 注意：
//   - SessionID 为空时拒绝恢复：mapEvent 按会话 id 过滤事件，空 id 会把全部
//     事件当「其他会话」丢弃，静默恢复等于无声断流，宁可交协调者裁决
//   - 重启时正在进行的回合文本累积在内存里已丢失：重建后的回合从 SSE 重放的新
//     快照重新累积（partSeen/partSnap 重新对账），idle 分类的 git 基线以重启
//     时刻的 HEAD 为准——这是 MVP 接受的缝隙，由 e2e 清单「agentd 重启」项
//     实测观察
//   - 与 Start 的对称性：Stop（done 归档）对恢复出来的运行态同样有效，
//     会按进程组 Kill 回收执行者资源
func (a *Adapter) Resume(req executor.ResumeReq) (out executor.ResumeOutcome, err error) {
	a.log.Info("adapter 恢复任务执行", "task", req.TaskID, "session", req.SessionID)
	defer func() {
		if err != nil {
			a.log.Error("adapter 恢复任务失败", "task", req.TaskID, "cause", err)
		} else if out.Alive {
			a.log.Info("adapter 任务已恢复", "task", req.TaskID, "session", out.SessionID)
		}
	}()

	a.mu.Lock()
	if _, busy := a.runs[req.TaskID]; busy {
		a.mu.Unlock()
		a.log.Info("该任务已有运行态或恢复进行中，跳过本次恢复", "task", req.TaskID)
		return executor.ResumeOutcome{Alive: false, Note: "该任务的恢复正在进行中"}, nil
	}
	a.runs[req.TaskID] = &runState{taskID: req.TaskID}
	a.mu.Unlock()
	defer func() {

		a.mu.Lock()
		if cur, ok := a.runs[req.TaskID]; ok && cur.evCh == nil {
			delete(a.runs, req.TaskID)
		}
		a.mu.Unlock()
	}()

	if req.SessionID == "" {
		return executor.ResumeOutcome{}, fmt.Errorf("任务 %s 缺 executor_session，无法重建订阅", req.TaskID)
	}
	si, err := readProcInfo(req.TaskDir)
	if err != nil {
		return executor.ResumeOutcome{}, err
	}

	proc := &Proc{Handle: si.Handle, Port: si.Port, Password: si.Password,
		ServeLogPath:	filepath.Join(req.TaskDir, serveLogFileName)}

	mode := executor.ResumeModeReattach
	if !proc.Alive() {

		if kerr := proc.Kill(); kerr != nil {
			a.log.Warn("回收已死执行者失败，可能需人工清理",
				"task", req.TaskID, "shim_pid", proc.Handle.PID, "cause", kerr)
		}
		if !req.Cold {
			a.log.Info("serve 已不在且不允许冷恢复，判不可恢复",
				"task", req.TaskID, "shim_pid", proc.Handle.PID)
			return executor.ResumeOutcome{Alive: false,
				Note:	"serve 进程已不在（本次只允许热重连）"}, nil
		}

		if _, serr := os.Stat(req.TaskDir); serr != nil {
			a.log.Info("任务目录已不存在，判不可恢复", "task", req.TaskID, "cause", serr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务目录已不存在（可能已归档清理），无法恢复"}, nil
		}
		if _, rerr := os.Stat(req.RepoPath); rerr != nil {
			a.log.Info("任务工作区已不存在，判不可恢复", "task", req.TaskID, "cause", rerr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务工作区已不存在（可能已归档清理），无法恢复"}, nil
		}
		a.log.Info("serve 已不在，进入冷恢复", "task", req.TaskID, "session", req.SessionID)

		configPath := filepath.Join(req.TaskDir, configFileName)
		tmpDir, managedEnv := managedTaskTmpEnv(req.TaskDir, req.TaskID)
		if err := ensureTaskTmp(req.TaskID, tmpDir, a.log); err != nil {
			return executor.ResumeOutcome{}, fmt.Errorf("创建任务临时目录 %s: %w", tmpDir, err)
		}
		env := append(append([]string{}, req.Env...), managedEnv...)
		newProc, err := startServe(context.Background(), req.RepoPath, req.TaskID, req.MarkRoot,
			req.TaskDir, configPath, env, a.log)
		if err != nil {
			a.log.Warn("冷恢复重起 serve 失败，判不可恢复", "task", req.TaskID, "cause", err)
			return executor.ResumeOutcome{Alive: false,
				Note:	fmt.Sprintf("重起 opencode serve 失败：%v", err)}, nil
		}

		if werr := writeProcInfo(req.TaskDir, &procInfo{
			Handle:	newProc.Handle, Port: newProc.Port, Password: newProc.Password,
			LastTurnMsgID:	si.LastTurnMsgID, WatermarkArmed: si.WatermarkArmed,
		}); werr != nil {
			a.log.Warn("冷恢复写 proc.json 失败，下次重启恢复将不可用",
				"task", req.TaskID, "cause", werr)
		}
		proc = newProc
		mode = executor.ResumeModeCold
		a.log.Info("冷恢复新 serve 就绪", "task", req.TaskID, "port", proc.Port)
	}
	if mode == executor.ResumeModeCold && req.Approval == nil {
		return executor.ResumeOutcome{}, fmt.Errorf("OpenCode 冷恢复必须注入 ApprovalClient；nil 不是全部免审")
	}
	r := a.newRun(req.TaskID, req.TaskDir, req.RepoPath)
	r.approval = req.Approval
	sessionID := req.SessionID
	r.session = sessionID
	r.api = NewAPI(fmt.Sprintf("http://127.0.0.1:%d", proc.Port), proc.Password)
	r.handle = procHandle{p: proc}

	if mode == executor.ResumeModeCold {

		has, err := r.api.HasSession(context.Background(), sessionID)
		if err != nil {
			a.log.Warn("查询会话列表失败，保守降级新会话", "task", req.TaskID, "cause", err)
			has = false
		}
		if !has {
			newID, nerr := r.api.CreateSession(context.Background())
			if nerr != nil {
				a.log.Warn("降级新建会话失败，判不可恢复", "task", req.TaskID, "cause", nerr)
				a.drop(req.TaskID)
				return executor.ResumeOutcome{Alive: false,
					Note:	fmt.Sprintf("原会话已不在且新建失败：%v", nerr)}, nil
			}
			a.log.Warn("原会话已不在，已新开会话", "task", req.TaskID,
				"old", sessionID, "new", newID)
			sessionID, mode = newID, executor.ResumeModeFresh

			if werr := writeProcInfo(req.TaskDir, &procInfo{
				Handle:	proc.Handle, Port: proc.Port, Password: proc.Password,
				WatermarkArmed:	true,
			}); werr != nil {
				a.log.Warn("新会话清零对账水位失败", "task", req.TaskID, "cause", werr)
			}
		}
		r.session = sessionID
	}
	r.captureStartCommit(a)
	go r.subscribeLoop(a)
	go a.watchdog(r)

	if mode != executor.ResumeModeFresh {
		go a.reconcileAfterRecovery(context.Background(), req.TaskID, "startup")
		go a.rediscoverPendingQuestions(context.Background(), req.TaskID)

		go a.rediscoverPendingPermissions(context.Background(), req.TaskID)
	}
	return executor.ResumeOutcome{
		Alive:	true, Mode: mode, SessionID: sessionID,
		Note:	resumeNote(mode, sessionID),
	}, nil
}

n_opencode_Adapter_Resume.signatureOld:
// Resume 重建 agentd 重启前已在执行的任务（spec §8「存活则重连 SSE 继续」）：
// 从任务目录的 proc.json 恢复 serve 连接凭据并探活（存活锁 + HTTP 应答）；
// 存活则重建 SSE 订阅、看门狗与事件通道，返回 Reattach。
//
// 参数：
//   - req: 恢复请求（TaskDir 是 proc.json 所在，即 DataDir/tasks/<id>；
//     RepoPath 用于重启后重新捕获 git 兜底分类的起点 commit 基线；
//     SessionID 是落库的 opencode 会话 id）
//
// 返回：
//   - Alive=false 时调用方（manager）把任务转 failed 交协调者裁决（保守优于静默）
//   - err: 重建失败（proc.json 缺失/损坏、SessionID 为空），此时视为不可恢复
//
// 注意：
//   - SessionID 为空时拒绝恢复：mapEvent 按会话 id 过滤事件，空 id 会把全部
//     事件当「其他会话」丢弃，静默恢复等于无声断流，宁可交协调者裁决
//   - 重启时正在进行的回合文本累积在内存里已丢失：重建后的回合从 SSE 重放的新
//     快照重新累积（partSeen/partSnap 重新对账），idle 分类的 git 基线以重启
//     时刻的 HEAD 为准——这是 MVP 接受的缝隙，由 e2e 清单「agentd 重启」项
//     实测观察
//   - 与 Start 的对称性：Stop（done 归档）对恢复出来的运行态同样有效，
//     会按进程组 Kill 回收执行者资源
func (a *Adapter) Resume(req executor.ResumeReq) (out executor.ResumeOutcome, err error) {
	a.log.Info("adapter 恢复任务执行", "task", req.TaskID, "session", req.SessionID)
	defer func() {
		if err != nil {
			a.log.Error("adapter 恢复任务失败", "task", req.TaskID, "cause", err)
		} else if out.Alive {
			a.log.Info("adapter 任务已恢复", "task", req.TaskID, "session", out.SessionID)
		}
	}()

	a.mu.Lock()
	if _, busy := a.runs[req.TaskID]; busy {
		a.mu.Unlock()
		a.log.Info("该任务已有运行态或恢复进行中，跳过本次恢复", "task", req.TaskID)
		return executor.ResumeOutcome{Alive: false, Note: "该任务的恢复正在进行中"}, nil
	}
	a.runs[req.TaskID] = &runState{taskID: req.TaskID}
	a.mu.Unlock()
	defer func() {

		a.mu.Lock()
		if cur, ok := a.runs[req.TaskID]; ok && cur.evCh == nil {
			delete(a.runs, req.TaskID)
		}
		a.mu.Unlock()
	}()

	if req.SessionID == "" {
		return executor.ResumeOutcome{}, fmt.Errorf("任务 %s 缺 executor_session，无法重建订阅", req.TaskID)
	}
	si, err := readProcInfo(req.TaskDir)
	if err != nil {
		return executor.ResumeOutcome{}, err
	}

	proc := &Proc{Handle: si.Handle, Port: si.Port, Password: si.Password,
		ServeLogPath:	filepath.Join(req.TaskDir, serveLogFileName)}

	mode := executor.ResumeModeReattach
	if !proc.Alive() {

		if kerr := proc.Kill(); kerr != nil {
			a.log.Warn("回收已死执行者失败，可能需人工清理",
				"task", req.TaskID, "shim_pid", proc.Handle.PID, "cause", kerr)
		}
		if !req.Cold {
			a.log.Info("serve 已不在且不允许冷恢复，判不可恢复",
				"task", req.TaskID, "shim_pid", proc.Handle.PID)
			return executor.ResumeOutcome{Alive: false,
				Note:	"serve 进程已不在（本次只允许热重连）"}, nil
		}

		if _, serr := os.Stat(req.TaskDir); serr != nil {
			a.log.Info("任务目录已不存在，判不可恢复", "task", req.TaskID, "cause", serr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务目录已不存在（可能已归档清理），无法恢复"}, nil
		}
		if _, rerr := os.Stat(req.RepoPath); rerr != nil {
			a.log.Info("任务工作区已不存在，判不可恢复", "task", req.TaskID, "cause", rerr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务工作区已不存在（可能已归档清理），无法恢复"}, nil
		}
		a.log.Info("serve 已不在，进入冷恢复", "task", req.TaskID, "session", req.SessionID)

		configPath := filepath.Join(req.TaskDir, configFileName)
		tmpDir, managedEnv := managedTaskTmpEnv(req.TaskDir, req.TaskID)
		if err := ensureTaskTmp(req.TaskID, tmpDir, a.log); err != nil {
			return executor.ResumeOutcome{}, fmt.Errorf("创建任务临时目录 %s: %w", tmpDir, err)
		}
		env := append(append([]string{}, req.Env...), managedEnv...)
		newProc, err := startServe(context.Background(), req.RepoPath, req.TaskID, req.MarkRoot,
			req.TaskDir, configPath, env, a.log)
		if err != nil {
			a.log.Warn("冷恢复重起 serve 失败，判不可恢复", "task", req.TaskID, "cause", err)
			return executor.ResumeOutcome{Alive: false,
				Note:	fmt.Sprintf("重起 opencode serve 失败：%v", err)}, nil
		}

		if werr := writeProcInfo(req.TaskDir, &procInfo{
			Handle:	newProc.Handle, Port: newProc.Port, Password: newProc.Password,
			LastTurnMsgID:	si.LastTurnMsgID, WatermarkArmed: si.WatermarkArmed,
		}); werr != nil {
			a.log.Warn("冷恢复写 proc.json 失败，下次重启恢复将不可用",
				"task", req.TaskID, "cause", werr)
		}
		proc = newProc
		mode = executor.ResumeModeCold
		a.log.Info("冷恢复新 serve 就绪", "task", req.TaskID, "port", proc.Port)
	}
	if mode == executor.ResumeModeCold && req.Approval == nil {
		return executor.ResumeOutcome{}, fmt.Errorf("OpenCode 冷恢复必须注入 ApprovalClient；nil 不是全部免审")
	}
	r := a.newRun(req.TaskID, req.TaskDir, req.RepoPath)
	r.approval = req.Approval
	sessionID := req.SessionID
	r.session = sessionID
	r.api = NewAPI(fmt.Sprintf("http://127.0.0.1:%d", proc.Port), proc.Password)
	r.handle = procHandle{p: proc}

	if mode == executor.ResumeModeCold {

		has, err := r.api.HasSession(context.Background(), sessionID)
		if err != nil {
			a.log.Warn("查询会话列表失败，保守降级新会话", "task", req.TaskID, "cause", err)
			has = false
		}
		if !has {
			newID, nerr := r.api.CreateSession(context.Background())
			if nerr != nil {
				a.log.Warn("降级新建会话失败，判不可恢复", "task", req.TaskID, "cause", nerr)
				a.drop(req.TaskID)
				return executor.ResumeOutcome{Alive: false,
					Note:	fmt.Sprintf("原会话已不在且新建失败：%v", nerr)}, nil
			}
			a.log.Warn("原会话已不在，已新开会话", "task", req.TaskID,
				"old", sessionID, "new", newID)
			sessionID, mode = newID, executor.ResumeModeFresh

			if werr := writeProcInfo(req.TaskDir, &procInfo{
				Handle:	proc.Handle, Port: proc.Port, Password: proc.Password,
				WatermarkArmed:	true,
			}); werr != nil {
				a.log.Warn("新会话清零对账水位失败", "task", req.TaskID, "cause", werr)
			}
		}
		r.session = sessionID
	}
	r.captureStartCommit(a)
	go r.subscribeLoop(a)
	go a.watchdog(r)

	if mode != executor.ResumeModeFresh {
		go a.reconcileAfterRecovery(context.Background(), req.TaskID, "startup")
		go a.rediscoverPendingQuestions(context.Background(), req.TaskID)
	}
	return executor.ResumeOutcome{
		Alive:	true, Mode: mode, SessionID: sessionID,
		Note:	resumeNote(mode, sessionID),
	}, nil
}

n_opencode_Adapter_acceptForeign.signature:
// acceptForeign 裁决一条「会话 id 与本任务不符」的事件是否仍要处理，
// 并保证两个方向都不静默。
//
// 参数：
//   - sessionID: 从顶层或 properties 提取到的会话 id（"" 表示事件没带）
//
// 返回：
//   - true 表示继续按本任务的事件处理，false 表示丢弃
//
// why（三条实测结论，改这里之前先读）：
//   - opencode 会为 subagent/task 工具派生子会话，其权限请求带子会话 id。
//     GET /session/{id} 返回 parentID，**父子关系端点是存在的**——本函数早期
//     版本的注释断言「本层无法把子会话映射回任务」，那是错的，B52 已实测推翻：
//     子会话的 parentID 就等于本任务的会话 id
//   - 子会话被 opencode 自己下了 permission:[{task,*,deny}]，不能再派生 subagent，
//     所以嵌套深度恒为 1，比一次 parentID 就够，不需要向上遍历
//   - 每个任务起自己的 opencode serve（见 proc.go 的 freePort），所以 /event 的
//     「全服务器广播」实际是「本任务这一个 serve 的广播」，流上出现的陌生会话
//     本就只可能是本任务自己派生的子会话
//
// why 仍然保留校验（不能改成一律放行）：校验存在的理由是防止跨任务串台。
// 缺 sessionID 的任务级事件更不能 fail-open——一条无归属的 permission.asked
// 会被当成本任务的审批门，协调者的批准动作会发到错误的会话。
func (a *Adapter) acceptForeign(r *runState, ev sseEvent, sessionID string) bool {
	if !taskScopedEvents[ev.Type] {
		return true
	}
	if ev.Type == "permission.asked" {
		if sessionID == "" {
			a.log.Warn("收到不带会话 id 的审批请求，无法归属，未产出工单",
				"task", r.taskID, "own_session", r.session,
				"properties", turn.TruncateRunes(string(ev.Properties), 200))
			a.emitOwnershipFailure(r, sessionID, "事件未携带会话 id")
			return false
		}
		if _, ok := a.resolveChildSession(r, sessionID); ok {
			return true
		}
		a.emitOwnershipFailure(r, sessionID, "认亲失败")
		return false
	}

	a.log.Debug("收到其他会话事件，跳过", "task", r.taskID,
		"type", ev.Type, "session", sessionID)
	return false
}

n_opencode_Adapter_advanceWatermark.signature:
// advanceWatermark 把本回合最后一条 assistant 消息 id 落进 proc.json，作为对账水位。
//
// why（正常路径也必须写）：对账靠「会话尾部消息 id != 水位」判定「有未消费的
// 已完结回合」。若只在对账成功时写水位，一个正常送达的终态就不会推进水位，
// 下一次对账会把它当成丢失事件**重复补发**一遍。
//
// 失败只 Warn 不中断：水位写不进去的后果是下次可能重复补发一条终态（事件表多
// 一条、状态机 waiting_review→waiting_review 被 ErrBadTransit 挡掉），比中断
// 回合分类轻得多。
func (a *Adapter) advanceWatermark(r *runState) {
	msgID := r.lastAssistantMsgID
	if msgID == "" {
		a.log.Debug("本回合无 assistant 消息 id，跳过水位前进", "task", r.taskID)
		return
	}
	pi, err := readProcInfo(r.taskDir)
	if err != nil {
		a.log.Warn("前进对账水位失败：读凭据出错，下次对账可能重复补发",
			"task", r.taskID, "msg", msgID, "cause", err)
		return
	}
	if pi.LastTurnMsgID == msgID {
		return
	}
	old := pi.LastTurnMsgID
	pi.LastTurnMsgID = msgID
	if err := writeProcInfo(r.taskDir, pi); err != nil {
		a.log.Warn("前进对账水位失败：写凭据出错，下次对账可能重复补发",
			"task", r.taskID, "msg", msgID, "cause", err)
		return
	}
	a.log.Info("对账水位已前进", "task", r.taskID, "from", old, "to", msgID)
}

n_opencode_Adapter_classifyReconciled.signature:
// classifyReconciled 把取回的消息翻译成一条与实时路径同形的 AdapterEvent。
//
// 分类**复用** turn.ParseTrailer——与 mapIdle 走同一套判据，于是以提问收尾的
// 回合会正确地还原成 question 工单，而不是一条假的「做完了」。
//
// 返回：事件本身，以及一句给协调者看的结论。
func (a *Adapter) classifyReconciled(r *runState, msg *SessionMessage) (executor.AdapterEvent, string) {

	if msg.ErrorName == "MessageAbortedError" {
		text := "断连期间该会话被人工 abort 解开（可能是救援动作）。回合停在这里等人指路，"
		if msg.Text != "" {
			text += "回合原文：\n" + turn.TailRunes(msg.Text, 1000)
		}
		a.log.Warn("对账发现回合被 abort，转提问交协调者裁决",
			"task", r.taskID, "msg", msg.ID)
		return executor.AdapterEvent{Type: "question", SessionID: r.session,
				Text:	turn.ClampQuestion(text)},
			"补回了一条断连期间被 abort 的回合（需人工裁决，含原文）"
	}
	if msg.ErrorText != "" {
		a.log.Warn("对账发现回合以错误告终", "task", r.taskID, "msg", msg.ID,
			"error", turn.TruncateRunes(msg.ErrorText, 200))
		return executor.AdapterEvent{Type: "result", SessionID: r.session,
				Result: &executor.Result{OK: false,
					FailReason: "回合在 agentd 断连期间以错误告终：" +
						turn.TruncateRunes(msg.ErrorText, 200)}},
			"补回了一条断连期间丢失的失败结果"
	}

	if msg.ToolStatus == "error" {
		text := "断连期间该回合以工具被拒或工具报错告终"
		if msg.Text != "" {
			text += "，回合原文：\n" + turn.TailRunes(msg.Text, 1000)
		}
		a.log.Warn("对账发现回合以工具错误告终，转提问交协调者裁决",
			"task", r.taskID, "msg", msg.ID)
		return executor.AdapterEvent{Type: "question", SessionID: r.session,
				Text:	turn.ClampQuestion(text)},
			"补回了一条断连期间丢失的回合（工具被拒/报错而终），需人工裁决"
	}
	kind, t := turn.ParseTrailer(msg.Text)
	switch kind {
	case "ask":
		return executor.AdapterEvent{Type: "question", SessionID: r.session,
			Text:	turn.ClampQuestion(t.Question)}, "补回了一条断连期间丢失的提问"
	case "finish":
		return executor.AdapterEvent{Type: "result", SessionID: r.session,
			Result: &executor.Result{OK: true, Branch: t.Branch, CommitHash: t.Commit,
				Summary:	t.Summary, SessionID: r.session}}, "补回了一条断连期间丢失的完成结果"
	}

	a.log.Warn("对账发现回合无协议 trailer，转提问交协调者裁决",
		"task", r.taskID, "msg", msg.ID)
	return executor.AdapterEvent{Type: "question", SessionID: r.session,
		Text: turn.ClampQuestion("agentd 断连期间该回合已结束，但未输出协议结论。" +
			"回合原文：\n" + turn.TailRunes(msg.Text, 1000))}, "补回了一条断连期间丢失的回合，需人工裁决"
}

n_opencode_Adapter_emit.signature:
// emit 向事件通道投递一条 AdapterEvent 并打产出日志（所有事件统一的出口）。
//
// 同时为看门狗打活跃点（lastEventAt）：探活降频的「收到新事件回高频」信号
// （P1-17，见 watchdogWithConfig）。
//
// 并发：订阅 goroutine 与 idle 去抖定时器 goroutine 都会 emit，故写入与关闭
// 统一由 emitMu 串行化，evClosed 使关闭后的迟到投递静默丢弃而非 panic。
//
// 返回 false 表示 Stop 已关闭 stopCh 或通道已关闭，事件未被投递。
func (a *Adapter) emit(r *runState, ev executor.AdapterEvent) bool {
	r.lastEventAt.Store(time.Now().UnixNano())
	switch ev.Type {
	case "permission":
		a.log.Info("adapter 产出权限事件", "task", r.taskID, "type", ev.Type,
			"perm", ev.PermissionID, "text", turn.TruncateRunes(ev.Text, 80))
	case "question":
		a.log.Info("adapter 产出提问事件", "task", r.taskID, "type", ev.Type,
			"text", turn.TruncateRunes(ev.Text, 80))
	case "progress":
		a.log.Info("adapter 产出进度事件", "task", r.taskID, "type", ev.Type,
			"text", turn.TruncateRunes(ev.Text, 80))
	case "result":
		ok := ev.Result != nil && ev.Result.OK
		a.log.Info("adapter 产出结果事件", "task", r.taskID, "type", ev.Type, "ok", ok)
	case "usage":

	default:
		a.log.Info("adapter 产出未知事件", "task", r.taskID, "type", ev.Type)
	}
	r.emitMu.Lock()
	defer r.emitMu.Unlock()
	if r.evClosed {
		a.log.Debug("事件通道已关闭，丢弃迟到事件", "task", r.taskID, "type", ev.Type)
		return false
	}
	select {
	case r.evCh <- ev:
		return true
	case <-r.stopCh:
		return false
	}
}

n_opencode_Adapter_emitOwnershipFailure.signature:
// emitOwnershipFailure 把一次归属判定失败播报给协调者。
//
// 参数：
//   - sessionID: 判定失败的会话 id（可能为空串）
//   - reason:    失败原因短语，进 progress 文本
//
// why：丢弃一条审批请求意味着 opencode 在等一个永远不会到来的决策，而 serve
// 活着、看门狗不触发——只写日志的话协调者在 handoff 里完全看不见。progress
// 只入库不阻塞，是把这件事送到 handoff show 事件历史的最轻通道。
func (a *Adapter) emitOwnershipFailure(r *runState, sessionID, reason string) {
	if sessionID == "" {
		sessionID = "(未携带)"
	}
	a.emit(r, executor.AdapterEvent{
		Type:	"progress",
		Text: "丢弃了一条无法归属的审批请求（" + reason + "，会话 " + sessionID +
			"）：opencode 可能在等一个看不见的决策，任务若卡住请 handoff attach 查看现场",
	})
}

n_opencode_Adapter_fallbackClassify.signature:
// fallbackClassify 是「模型未按纪律输出协议 trailer」的兜底分类。
//
// why（兜底分类规则）：回合结束但 turn.ParseTrailer 判 none。此时拿 git 实况裁决：
//   - 相对回合起点有新 commit → 发 result{OK:false}（B74）。**不替模型宣布完成**：
//     模型没说完成，handoff 就不说。翻转不给协调者加任何一次操作——OK 与 !OK
//     都落 waiting_review，done 与 continue 在那里都合法；变的只是事件从
//     「已完成，摘要如下」变成「有新提交，但模型未按纪律宣布完成」。
//   - 没有新 commit / git 查询失败 → 把回合全文交协调者裁决（question），流程不卡死。
func (a *Adapter) fallbackClassify(r *runState, text string) {
	a.log.Warn("回合未输出协议 trailer，走 git 兜底", "task", r.taskID,
		"turn_tail", turn.TailRunes(text, 120))
	branch, commit, hasNew, err := a.gitTurnStatus(r)
	if err != nil || !hasNew {
		if err != nil {
			a.log.Error("git 兜底查询失败", "task", r.taskID, "cause", err)
		}
		a.log.Info("兜底判定无新提交，转提问交协调者裁决", "task", r.taskID, "has_new", hasNew)
		a.emit(r, executor.AdapterEvent{Type: "question", Text: turn.ClampQuestion(text)})
		return
	}
	a.log.Warn("兜底判定有新提交，但模型未宣布完成，转失败交协调者裁决",
		"task", r.taskID, "branch", branch, "commit", commit)
	a.emit(r, executor.AdapterEvent{Type: "result",
		Result:	turn.NoTrailerResult(r.session, branch, commit, text)})
}

n_opencode_Adapter_flushPending.signature:
// flushPending 在 part 类型揭晓时处置它的暂存增量：是文本就落地进回合，
// 不是就整段丢弃（reasoning/tool 的增量绝不能进回合与 render.log）。
//
// W4a：丢弃前先按真实类型分流出一路帧——reasoning 的暂存增量落 reasoning 帧，
// 其余照旧整段丢弃。回合与 render.log 的走向一字不改。
//
// 为什么参数从 isText bool 换成 partType string：bool 分不出 reasoning 与
// tool，而这两者的帧处置不同（前者产帧、后者不产）。
func (a *Adapter) flushPending(r *runState, key, partType string) {
	buf, ok := r.pendingDelta[key]
	if !ok {
		return
	}
	delete(r.pendingDelta, key)
	r.pendingBytes -= len(buf)
	switch frameKind(partType) {
	case kindText:
		a.setPartText(r, key, r.partSeen[key]+buf)
		return
	case kindReasoning:
		if err := r.frames.Reasoning(key, buf); err != nil {
			a.log.Warn("写 reasoning 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
	}
	a.log.Debug("暂存增量所属 part 非文本，不进回合", "task", r.taskID,
		"type", partType, "bytes", len(buf))
}

n_opencode_Adapter_gitTurnStatus.signature:
// gitTurnStatus 查询仓库当前分支与 HEAD commit，并对比任务起点判定是否有新提交。
//
// 薄封装：实现在 turn 共享包（B2/B3 两个 adapter 同构逻辑），本方法保留
// 调用点已有的 r 上下文（repoPath/startCommit）。
func (a *Adapter) gitTurnStatus(r *runState) (branch, commit string, hasNew bool, err error) {
	return turn.GitTurnStatus(r.repoPath, r.startCommit)
}

n_opencode_Adapter_mapEvent.signature:
// mapEvent 把一条 SSE 事件映射为 0~N 条 AdapterEvent（宽容解析：未知事件
// Debug 跳过，绝不 panic、绝不中断订阅）。
func (a *Adapter) mapEvent(r *runState, raw json.RawMessage) {

	r.lastEventAt.Store(time.Now().UnixNano())
	var ev sseEvent
	if err := json.Unmarshal(raw, &ev); err != nil {
		a.log.Debug("SSE 事件解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}

	sessionID := ev.SessionID
	if sessionID == "" {
		var prop struct {
			SessionID string `json:"sessionID"`
		}
		if json.Unmarshal(ev.Properties, &prop) == nil {
			sessionID = prop.SessionID
		}
	}
	if sessionID != r.session && !a.acceptForeign(r, ev, sessionID) {
		return
	}

	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	switch {
	case ev.Type == "permission.asked":
		a.mapPermissionAsked(r, ev.Properties)
	case ev.Type == "permission.replied":

		a.log.Debug("permission.replied 应答回显，忽略", "task", r.taskID, "type", ev.Type)
	case ev.Type == "question.asked":
		a.mapQuestionAsked(r, ev.Properties)
	case ev.Type == "question.replied", ev.Type == "question.rejected":

		a.log.Debug("question 应答回显，忽略", "task", r.taskID, "type", ev.Type)
	case ev.Type == "message.updated":
		a.mapMessageUpdated(r, ev.Properties)
	case ev.Type == "message.part.updated":
		a.mapPartUpdated(r, ev.Properties)
	case ev.Type == "message.part.delta":
		a.mapPartDelta(r, ev.Properties)
	case ev.Type == "session.status":
		a.mapSessionStatus(r, ev.Properties)
	case ev.Type == "session.idle":

		a.log.Debug("session.idle 与 session.status idle 同现，忽略防重复触发",
			"task", r.taskID, "type", ev.Type)
	case ev.Type == "session.error":
		a.log.Warn("opencode 会话报错", "task", r.taskID,
			"properties", turn.TruncateRunes(string(ev.Properties), 200))
	default:
		a.log.Debug("未知 SSE 事件，跳过", "task", r.taskID, "type", ev.Type)
	}
}

n_opencode_Adapter_mapIdle.signature:
// mapIdle 回合结束（session.status idle 主信号）时分类收尾：turn.ParseTrailer 判定
// ask/finish/none，none 走 git 实况兜底（why 见 fallbackClassify）。分类后清空
// 回合缓冲。
//
// 空回合（无累积文本）不再静默跳过：零文本转失败结果交协调者（B21）——idle 但
// 无文本说明文本流没被本层接住（事件结构变化/增量对账失败）或供应商流中断，
// 这是「任务可能静默挂死」的观测点，必须产事件而非 Debug 静默。被拒终止的
// 空回合例外，它走 question（有内容可问，见下文）。props 为触发 idle 的
// session.status 载荷，仅用于日志上下文。
func (a *Adapter) mapIdle(r *runState, raw json.RawMessage) {

	a.reportTiming(r, r.seg.EndTurn())
	text := r.turnText()
	if strings.TrimSpace(text) == "" {

		if rejected := r.takeTurnRejected(); len(rejected) > 0 {
			a.log.Warn("回合因权限被拒终止且无文本产出，转提问交协调者裁决",
				"task", r.taskID, "rejected", rejected)
			a.emit(r, executor.AdapterEvent{
				Type:	"question", Text: turn.ClampQuestion(rejectedTurnQuestion(rejected)),
			})
			a.advanceWatermark(r)
			r.clearTurn()
			r.takeAskedViaTool()
			r.captureStartCommit(a)
			return
		}

		a.log.Warn("idle 但回合无文本，转失败结果交协调者", "task", r.taskID,
			"event", turn.TailRunes(string(raw), 120))
		a.emit(r, executor.AdapterEvent{Type: "result", SessionID: r.session, Result: &executor.Result{
			OK:	false,
			FailReason: "回合结束但零文本产出（可能是供应商流中断）；executor 仍在线，" +
				"可 continue 续接重试",
		}})
		a.advanceWatermark(r)
		r.clearTurn()
		r.takeAskedViaTool()
		r.captureStartCommit(a)
		return
	}

	askedViaTool := r.takeAskedViaTool()
	kind, t := turn.ParseTrailer(text)
	a.log.Info("opencode 回合收尾", "task", r.taskID, "kind", kind,
		"asked_via_tool", askedViaTool, "final_text_len", len([]rune(text)))
	switch kind {
	case "ask":

		if askedViaTool {
			a.log.Debug("本回合已通过 question 工具提问，抑制 trailer 提问工单",
				"task", r.taskID, "trailer_tail", turn.TailRunes(t.Question, 80))
			break
		}
		a.emit(r, executor.AdapterEvent{Type: "question", Text: turn.ClampQuestion(t.Question)})
	case "finish":
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	true, Branch: t.Branch, CommitHash: t.Commit,
			Summary:	t.Summary, SessionID: r.session,
			FinalText:	turn.FinalText(text),
		}})
	case "none":
		a.fallbackClassify(r, text)
	}
	a.advanceWatermark(r)
	r.clearTurn()

	r.captureStartCommit(a)
}

n_opencode_Adapter_mapMessageUpdated.signature:
// mapMessageUpdated 处理 message.updated：真实事件只携带 properties.info
// （role/messageID），不带文本——文本载体是 message.part.updated/delta。本层
// 只用它登记「哪些 messageID 属于 user」，这些消息的 text part 不进回合累积
// （回合只算模型输出）。
//
// why（不拿它清空回合）：user 消息曾被当作「新回合开始」的清空信号，但服务端
// 会重播同一条 user 消息（spike5 实测同一 msg id 出现 3 次，每次 session.diff
// 后一次）。进程内的 userMsgs 只在本次运行有效——agentd 重启后 Resume 出来的
// 运行态拿到的是空表，重播的老消息会被当「首见」而清空整个回合，恢复后累积的
// 文本全部丢弃、idle 走空回合分支永不分类，任务静默挂死（A-3）。回合缓冲由
// mapIdle 在分类后清空即可，不需要第二个清空信号。
func (a *Adapter) mapMessageUpdated(r *runState, props json.RawMessage) {

	if model, u, ok := parseMessageUsage(props); ok && (model != "" || u != nil) {
		a.emit(r, executor.AdapterEvent{Type: "usage", ActualModel: model, Usage: u})
	}

	if e, ok := parseMessageSpend(props); ok {
		a.emit(r, executor.AdapterEvent{Type: "usage", Spend: &e})
	}
	var msg struct {
		Info struct {
			ID	string	`json:"id"`
			Role	string	`json:"role"`
		} `json:"info"`
	}
	if err := json.Unmarshal(props, &msg); err != nil {
		a.log.Debug("message.updated 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if msg.Info.Role != "user" || msg.Info.ID == "" {
		return
	}
	r.userMsgs[msg.Info.ID] = true
}

n_opencode_Adapter_mapPartDelta.signature:
// mapPartDelta 处理 message.part.delta：field=text 的流式增量。
//
// why（已知类型才落地 + 未知类型暂存 + 与快照对账）：
//   - 只有**已登记为 text** 的 part 增量才进回合：partTypes 由 part.updated
//     登记（delta 本身只有 field 无类型，spike5 实测 reasoning 增量同样是
//     field=text），不加这道闸，reasoning/tool 增量会被当模型输出
//   - 类型未知时不猜（A-5）：「part.updated 总是先于 delta 到达」只是抓包里的
//     观测顺序，SSE 跨重连无顺序保证。猜 text 会泄漏思维链，直接丢弃会丢模型
//     输出——暂存进 pendingDelta，等 part.updated 揭示类型再落地或丢弃
//   - 若该 part 已收到非空全量快照（part.updated），增量已被快照覆盖，
//     跳过防重复；否则增量直接追加——真实流里「part 创建（空文本）→
//     逐条 delta 增长」期间并无有效快照可对账（spike5 实测）
func (a *Adapter) mapPartDelta(r *runState, props json.RawMessage) {
	var pd struct {
		MessageID	string	`json:"messageID"`
		PartID		string	`json:"partID"`
		Field		string	`json:"field"`
		Delta		string	`json:"delta"`
	}
	if err := json.Unmarshal(props, &pd); err != nil {
		a.log.Debug("message.part.delta 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if pd.Field != "text" || pd.Delta == "" || pd.MessageID == "" || pd.PartID == "" {
		return
	}
	if r.userMsgs[pd.MessageID] {
		return
	}
	r.lastAssistantMsgID = pd.MessageID
	key := partKey(pd.MessageID, pd.PartID)
	switch r.partTypes[key] {
	case "text":
		if r.partSnap[key] {
			return
		}
		a.setPartText(r, key, r.partSeen[key]+pd.Delta)
	case "":

		if r.pendingBytes+len(pd.Delta) > pendingDeltaLimit {
			a.log.Warn("类型未知的 part 增量超出暂存上限，丢弃",
				"task", r.taskID, "msg", pd.MessageID, "part", pd.PartID,
				"limit_bytes", pendingDeltaLimit)
			return
		}
		r.pendingDelta[key] += pd.Delta
		r.pendingBytes += len(pd.Delta)
	default:

		if frameKind(r.partTypes[key]) == kindReasoning {
			if err := r.frames.Reasoning(key, pd.Delta); err != nil {
				a.log.Warn("写 reasoning 帧失败，不影响回合", "task", r.taskID, "cause", err)
			}
		}
	}
}

n_opencode_Adapter_mapPartUpdated.signature:
// mapPartUpdated 处理 message.part.updated：text 类型 part 携带该 part 的
// 全量文本快照（真实流：文本首帧可能是空串的「part 创建」事件，随后走
// part.delta 增量，收尾再回发完整快照）。
//
// why（类型登记先于过滤 + 按 part 存当前值 + 与 delta 对账）：
//   - part 类型必须在 text 过滤前登记进 partTypes：message.part.delta 只有
//     field 没有 part 类型字段（spike5 实测 reasoning 增量也是 field=text），
//     part.updated 是唯一携带类型的事件——错过登记，reasoning/tool 增量会被
//     当模型输出累积进回合与 render.log。类型揭晓时还要处置该 part 在
//     pendingDelta 里的暂存增量（见 mapPartDelta）
//   - 服务端对同一 part 可能多次回发快照，且增量流结束后会补发全量快照——
//     按 messageID+partID 保存该 part 的当前文本，快照即覆盖，天然去重
//   - 快照不是已见文本的延续时（服务端修订了这一段），覆盖而非叠加：回合文本
//     与 render.log 都是给人读的，"Hello world" 改成 "Hi world" 不该读到
//     "Hello worldHi world"
//   - 空文本快照是 part 创建事件而非有效全量，不置 partSnap、也不清空已累积：
//     后续 delta 仍要照常累积（spike5 实测顺序：空快照 → delta 流 → 全量快照）
func (a *Adapter) mapPartUpdated(r *runState, props json.RawMessage) {
	var pu struct {
		Part struct {
			ID		string	`json:"id"`
			MessageID	string	`json:"messageID"`
			Type		string	`json:"type"`
			Text		string	`json:"text"`
			// 以下四个只在 type=="tool" 时有意义（见 mapToolPart）
			Tool	string	`json:"tool"`
			CallID	string	`json:"callID"`
			State	struct {
				Status	string		`json:"status"`
				Input	json.RawMessage	`json:"input"`
				Output	string		`json:"output"`
			}	`json:"state"`
		} `json:"part"`
	}
	if err := json.Unmarshal(props, &pu); err != nil {
		a.log.Debug("message.part.updated 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	p := pu.Part
	if p.ID == "" || p.MessageID == "" {
		return
	}
	key := partKey(p.MessageID, p.ID)

	r.partTypes[key] = p.Type
	if p.Type == "tool" {

		a.mapToolPart(r, p.Tool, toolPartKey(p.CallID, p.ID),
			p.State.Status, p.State.Input, p.State.Output)
	}
	isText := p.Type == "text" && !r.userMsgs[p.MessageID]
	if isText {
		r.lastAssistantMsgID = p.MessageID
	}

	pendingType := p.Type
	if p.Type == "text" && r.userMsgs[p.MessageID] {
		pendingType = "user-text"
	}
	a.flushPending(r, key, pendingType)
	if !isText {
		return
	}
	if p.Text == "" {
		return
	}
	r.partSnap[key] = true
	seen := r.partSeen[key]
	if p.Text == seen {
		return
	}
	if seen != "" && !strings.HasPrefix(p.Text, seen) {
		a.log.Debug("part 快照被服务端修订，按新快照覆盖",
			"task", r.taskID, "msg", p.MessageID, "part", p.ID)
	}
	a.setPartText(r, key, p.Text)
}

n_opencode_Adapter_mapPermissionAsked.signature:
// mapPermissionAsked 处理 permission.asked（真实事件）：properties.id 即
// PermissionID（manager 按其派生命名空间化的 ticket id，稳定幂等：SSE 重连
// 重放同一权限请求时复用同一 id，CreateTicket 按派生 id 去重）。
//
// 描述组合：permission 字段（如 bash） + metadata.command（如 echo spike-hi）；
// 无 command 时退回 patterns 拼接——尽量贴近工具将要执行的表述。
func (a *Adapter) mapPermissionAsked(r *runState, props json.RawMessage) {
	var pa struct {
		ID		string		`json:"id"`
		SessionID	string		`json:"sessionID"`
		Permission	string		`json:"permission"`
		Patterns	[]string	`json:"patterns"`
		Tool		struct {
			CallID string `json:"callID"`
		}	`json:"tool"`
		Metadata	struct {
			Command	string	`json:"command"`
			// filepath 是小写 p——真机样本如此（testdata/perm_edit.json）。
			// 写成 filePath 会静默取到空串，然后整条请求退化成「提取不出
			// 结构」被 fail-closed 升级，表现为每次编辑都唤醒人，很难查。
			FilePath	string	`json:"filepath"`
			// external_directory 的 bash 形态没有 filepath，越界目录在这里
			ParentDir	string		`json:"parentDir"`
			Directories	[]string	`json:"directories"`
		}	`json:"metadata"`
	}
	if err := json.Unmarshal(props, &pa); err != nil {
		a.log.Debug("permission.asked 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if pa.ID == "" {
		a.log.Debug("permission.asked 事件缺 id，跳过", "task", r.taskID)
		return
	}
	text := pa.Permission
	if cmd := pa.Metadata.Command; cmd != "" {
		text += ": " + cmd
	} else if len(pa.Patterns) > 0 {
		text += ": " + strings.Join(pa.Patterns, " ")
	}

	if strings.TrimSpace(text) == "" {
		a.log.Warn("permission.asked 无可读描述，按未说明权限交协调者",
			"task", r.taskID, "perm", pa.ID)
		text = "opencode 未提供权限描述（id " + pa.ID + "），请 handoff attach 查看现场"
	}

	permSess := pa.SessionID
	if permSess == "" {
		permSess = r.session
	}
	if permSess != r.session {
		r.sessMu.RLock()
		title := r.childSessions[permSess]
		r.sessMu.RUnlock()
		if title != "" {
			text = "[子 agent: " + title + "] " + text
		} else {

			text = "[子 agent] " + text
		}
	}
	r.sessMu.Lock()
	r.permSession[pa.ID] = permSess
	r.sessMu.Unlock()
	a.log.Info("权限请求已归属会话", "task", r.taskID, "perm", pa.ID,
		"session", permSess, "is_child", permSess != r.session)

	r.permText[pa.ID] = text
	if pa.Tool.CallID == "" {
		a.log.Warn("opencode 权限请求缺少 tool.callID，不暂停未知工具",
			"task", r.taskID, "perm", pa.ID, "session", permSess)
	} else {
		r.sessMu.Lock()
		if r.permTiming == nil {
			r.permTiming = map[string]permissionTiming{}
		}
		_, duplicate := r.permTiming[pa.ID]
		if !duplicate {
			r.permTiming[pa.ID] = permissionTiming{part: pa.Tool.CallID, paused: true}
		}
		r.sessMu.Unlock()
		if duplicate {
			a.log.Debug("重复 permission.asked 不重复暂停工具窗口",
				"task", r.taskID, "perm", pa.ID, "part", pa.Tool.CallID)
		} else {
			a.log.Info("opencode 权限等待开始", "task", r.taskID,
				"perm", pa.ID, "part", pa.Tool.CallID, "session", permSess)
			entries := r.seg.PauseWaiting(pa.Tool.CallID)
			if len(entries) == 0 {
				a.log.Warn("opencode 权限请求未找到对应工具等待窗口",
					"task", r.taskID, "perm", pa.ID, "part", pa.Tool.CallID)
			} else {
				a.reportTiming(r, entries)
			}
		}
	}

	// 结构化载荷（B23/B27）：permission 字段就是 opencode 的工具类别原文，
	// 真机实测取值有 bash / edit / external_directory，直接作归一化来源。
	//
	// 为什么路径不取 patterns：patterns 里是相对路径与通配摘要（真机样本里
	// edit 的 patterns 是 ["probe.md"]、external_directory 的是 ["/tmp/*"]），
	// 拿它判归属会把通配符当成路径。绝对路径只在 metadata 里。
	var req *executor.PermRequest
	tool := executor.NormalizePermTool(pa.Permission)
	paths := pa.Metadata.Directories
	if pa.Metadata.FilePath != "" {
		paths = append([]string{pa.Metadata.FilePath}, paths...)
	}
	switch {
	case pa.Metadata.Command != "":
		if tool == executor.PermToolOther {
			tool = executor.PermToolBash
		}

		req = &executor.PermRequest{Tool: tool, Command: pa.Metadata.Command, Paths: paths}
	case len(paths) > 0:
		if tool == executor.PermToolOther {
			tool = executor.PermToolWrite
		}
		req = &executor.PermRequest{Tool: tool, Paths: paths}
	}
	if req == nil {

		a.log.Warn("opencode 权限请求提取不出结构化载荷，将由 manager 升级人工",
			"task", r.taskID, "perm", pa.ID, "permission", pa.Permission)
	}
	if r.approval != nil {
		ev := executor.AdapterEvent{Type: "permission", PermissionID: pa.ID,
			Text:	turn.TruncateMarked(text, permTextHardLimit), Perm: req}
		go a.authorizeNativePermission(r, ev)
		return
	}
	a.emit(r, executor.AdapterEvent{
		Type:	"permission", PermissionID: pa.ID,
		Text:	turn.TruncateMarked(text, permTextHardLimit),
		Perm:	req,
	})
}

n_opencode_Adapter_mapQuestionAsked.signature:
// mapQuestionAsked 处理 question.asked：opencode 原生 question 工具的提问请求。
//
// 与 permission.asked 同构（同一条 SSE 流上的并排事件），但有一处根本差别：
// **提问不结束回合**。question 工具阻塞等应答，session 不会转 idle，答复之后
// 是同一个回合继续——因此本函数**不得** clearTurn / advanceWatermark，
// 清缓冲会丢掉该回合已累积的文本，推进水位会让后续对账错位。
//
// 参数：props 为事件的 properties 原文（{id, sessionID, questions[], tool{}}）
//
// 注意：
//   - 本函数在 turnMu 下执行（见 mapEvent 的 switch 契约），可安全读写回合状态；
//     不得在此做网络 I/O
//   - 按 requestID 去重：seenQuestionIDs 只负责**进程内**的 SSE 重放去重；
//     跨进程（agentd 重启）的幂等由 manager 按事件上的 QuestionID 承担
func (a *Adapter) mapQuestionAsked(r *runState, props json.RawMessage) {
	var qa struct {
		ID		string		`json:"id"`
		SessionID	string		`json:"sessionID"`
		Questions	[]QuestionInfo	`json:"questions"`
	}
	if err := json.Unmarshal(props, &qa); err != nil {
		a.log.Debug("question.asked 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if qa.ID == "" {
		a.log.Debug("question.asked 事件缺 id，跳过", "task", r.taskID)
		return
	}
	if r.seenQuestionIDs[qa.ID] {
		a.log.Debug("question.asked 重复到达（SSE 重放），已忽略",
			"task", r.taskID, "request", qa.ID)
		return
	}
	r.seenQuestionIDs[qa.ID] = true

	text := renderQuestionTicket(qa.Questions)

	if len(qa.Questions) == 0 {
		a.log.Warn("question.asked 无问题内容，按未说明提问交协调者",
			"task", r.taskID, "request", qa.ID)
		text = "opencode 提出了一个空提问（id " + qa.ID + "），请 handoff attach 查看现场后作答"
	}

	qSess := qa.SessionID
	if qSess == "" {
		qSess = r.session
	}
	if qSess != r.session {
		r.sessMu.RLock()
		title := r.childSessions[qSess]
		r.sessMu.RUnlock()
		if title != "" {
			text = "[子 agent: " + title + "] " + text
		} else {
			text = "[子 agent] " + text
		}
	}

	r.pendingQuestionID = qa.ID
	r.pendingQuestions = qa.Questions

	r.askedViaTool = true

	a.log.Info("收到 executor 提问，转工单交协调者", "task", r.taskID,
		"request", qa.ID, "session", qSess, "is_child", qSess != r.session,
		"question_count", len(qa.Questions))
	a.emit(r, executor.AdapterEvent{
		Type:	"question", QuestionID: qa.ID, Text: turn.ClampQuestion(text),
	})

}

n_opencode_Adapter_mapSessionStatus.signature:
// mapSessionStatus 处理 session.status：status.type=idle 是回合结束的主信号
// （真实样本：{"type":"session.status","properties":{"status":{"type":"idle"}}}；
// busy 状态同结构，不触发）。同现的 session.idle 由 mapEvent 忽略防重复。
func (a *Adapter) mapSessionStatus(r *runState, props json.RawMessage) {
	var st struct {
		Status struct {
			Type string `json:"type"`
		} `json:"status"`
	}
	if err := json.Unmarshal(props, &st); err != nil {
		a.log.Debug("session.status 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if st.Status.Type == "idle" {
		a.scheduleIdle(r, props)
		return
	}

	r.idleGen++
}

n_opencode_Adapter_mapToolPart.signature:
// mapToolPart 把一次工具调用的推进落成帧 + 打点。调用方必须持有 r.turnMu。
//
// 参数：tool 是工具名（part.tool）；key 是配对键；status/input/output 取自
// part.state。
//
// 去重是本函数的主要职责：opencode 对同一个 tool part 会反复发 running
// （输出边长边发），终态也可能因 SSE 重放再来一次。toolStages 保证
// tool_call 帧与 tool_result 帧各恰好一条。
//
// 打点必须在写帧**之前**：写帧要过一次头尾截断与文件 IO，把那段时间算进
// 工具耗时是在给工具记别人的账。
//
// 为什么 dur 取 Segmenter 的墙钟而不是 part.state.time：state.time 记的是
// 「最后一次尝试」的起点，重试时会跳变、且不含权限审批等待（真机抓包实测：
// 同一个 callID 的 time.start 在一次审批前后从 …464643 跳到 …478355）。
// claudecode/codex 的工具耗时都含审批等待，取 state.time 会让 opencode 的
// 同一条命令看起来比别家快——那是**口径差不是性能差**（计划 §1.4 的拍板）。
func (a *Adapter) mapToolPart(r *runState, tool, key, status string,
	input json.RawMessage, output string) {
	if key == "" {
		return
	}
	st, terminal := toolResultStatus(status)

	if r.toolStages[key] == toolStageNone && (toolInputReady(input) || terminal) {
		r.toolStages[key] = toolStageStarted
		a.reportTiming(r, r.seg.ToolStart(key, tool, toolDetail(input)))

		if err := r.frames.ToolCall(key, tool, string(input)); err != nil {
			a.log.Warn("写 tool_call 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
	}
	if !terminal || r.toolStages[key] == toolStageDone {
		return
	}
	r.toolStages[key] = toolStageDone

	dur, entries := r.seg.ToolEnd(key)
	if err := r.frames.ToolResult(key, st, output, dur); err != nil {
		a.log.Warn("写 tool_result 帧失败，不影响回合", "task", r.taskID, "cause", err)
	}
	a.reportTiming(r, entries)
}

n_opencode_Adapter_maybeProgress.signature:
// maybeProgress 节流发 progress：每任务至多每 progressThrottle 一条
// （Task 12 e2e 遗留：按回合粒度细化）。
func (a *Adapter) maybeProgress(r *runState) {
	now := time.Now()
	if now.Sub(r.lastProgress) < progressThrottle {
		return
	}
	r.lastProgress = now
	a.emit(r, executor.AdapterEvent{Type: "progress", Text: turn.TailRunes(r.turnText(), 200)})
}

n_opencode_Adapter_reconcileAfterRecover.signature:
// reconcileAfterRecovery 是两个自动触发点共用的对账入口。
//
// 参数：
//   - ctx: 控制查询超时
//   - taskID: 目标任务
//   - trigger: 触发来源，只用于日志（"startup" = agentd 启动恢复，
//     "reconnect" = 连接断开重连）
//
// 注意：
//   - **不返回错误，且绝不 panic**：spec §6.3 的硬要求——对账失败不能阻断恢复。
//     一次网络抖动若能让 Resume 判不可恢复，比 B38 本身还糟
func (a *Adapter) reconcileAfterRecovery(ctx context.Context, taskID, trigger string) {
	out, err := a.Reconcile(ctx, taskID)
	if err != nil {
		a.log.Warn("恢复后对账失败，恢复本身不受影响",
			"task", taskID, "trigger", trigger, "cause", err)
		return
	}
	a.log.Info("恢复后对账完成", "task", taskID, "trigger", trigger,
		"turn_ended", out.TurnEnded, "emitted", out.Emitted, "note", out.Note)
}

n_opencode_Adapter_rediscoverPendingQues.signature:
// rediscoverPendingQuestions 在恢复后重新发现本任务挂起的提问并补发工单。
//
// 参数：taskID 为已完成运行态重建的任务 id
//
// 为什么必须有这一步：SSE 没有重放语义，agentd 重启窗口里发生的
// question.asked 永远收不到。而 opencode 侧的 question 工具还在阻塞等应答——
// 不重新发现，任务就是个谁也叫不醒的孤儿（与 B18/B20/B24 同一条纪律：
// 重启后一切「executor 那边还等着人」的状态都必须被重新发现）。
//
// 注意：
//   - GET /question 返回全部会话的挂起请求，必须按本任务的会话 id 过滤
//   - 本函数在 goroutine 里跑，不阻塞 Resume 返回；失败只记日志（挂起提问
//     发现不了仍有 stall 看门狗兜底，不该让恢复本身失败）
func (a *Adapter) rediscoverPendingQuestions(ctx context.Context, taskID string) {
	r := a.lookup(taskID)
	if r == nil || r.api == nil {
		a.log.Debug("重新发现挂起提问跳过：该任务无运行态", "task", taskID)
		return
	}
	pending, err := r.api.ListPendingQuestions(ctx)
	if err != nil {
		a.log.Warn("重新发现挂起提问失败，若确有挂起提问将由 stall 看门狗兜底",
			"task", taskID, "cause", err)
		return
	}
	for _, p := range pending {
		if p.SessionID != r.session {
			continue
		}
		r.turnMu.Lock()
		if r.seenQuestionIDs[p.ID] {
			r.turnMu.Unlock()
			continue
		}
		r.seenQuestionIDs[p.ID] = true
		r.pendingQuestionID = p.ID
		r.pendingQuestions = p.Questions
		r.turnMu.Unlock()

		a.log.Info("恢复后发现挂起提问，补发工单", "task", taskID,
			"request", p.ID, "question_count", len(p.Questions))

		a.emit(r, executor.AdapterEvent{Type: "question", QuestionID: p.ID,
			Text:	turn.ClampQuestion(renderQuestionTicket(p.Questions))})
		return
	}
	a.log.Info("恢复后未发现本任务的挂起提问", "task", taskID, "total_pending", len(pending))
}

n_opencode_Adapter_reportTiming.signature:
// reportTiming 把段切分器产出的条目逐条经 usage 事件上报。
//
// 为什么走 usage 而不是新事件类型：Usage（当前占用）、Spend（累计消耗）与
// Timing（耗时）是同一次模型调用结束时的三样产物；拆成两个事件，两者之间
// 就能插进一次 agentd 重启（契约文档 §6.3 的拍板记录）。
//
// entries 为空是常态（不是错误），静默返回。
func (a *Adapter) reportTiming(r *runState, entries []proto.TimingEntry) {
	for i := range entries {
		e := entries[i]
		if !a.emit(r, executor.AdapterEvent{Type: "usage", Timing: &e}) {
			a.log.Debug("opencode 耗时条目未能上报（事件通道已终止或已满）",
				"task", r.taskID, "key", e.Key, "remaining", len(entries)-i)
			return
		}
	}
}

n_opencode_Adapter_resolveChildSession.signature:
// resolveChildSession 判定一个陌生会话是否是本任务派生的子会话。
//
// 参数：
//   - sessionID: 事件携带的会话 id（调用方保证非空）
//
// 返回：
//   - title: 子会话标题（供工单标注）；认亲失败时为空
//   - ok:    是否认亲成功
//
// 注意：
//   - 只缓存正结果。一次网络抖动导致的判定失败若被缓存，这个子会话就被永久
//     拉黑，它后续每一条审批都会被丢弃——那正是本次要修的故障形态
//   - 不持 sessMu 跨 HTTP 调用：查缓存与写缓存各自短暂加锁，网络 I/O 不在锁下。
//     同一个新子会话的两条事件并发到达会各发一次 GET /session，幂等且无害，
//     不值得为它加 singleflight
//   - 不向上递归找祖先：opencode 自己给 subagent 下了 permission:[{task,*,deny}]
//     （真机实测），嵌套深度恒为 1。真出现二级说明这条不变量被打破了，那是断言
//     失败，该报警而不是在事件热路径上做无界遍历
func (a *Adapter) resolveChildSession(r *runState, sessionID string) (title string, ok bool) {
	r.sessMu.RLock()
	title, cached := r.childSessions[sessionID]
	r.sessMu.RUnlock()
	if cached {
		a.log.Debug("子会话认亲命中缓存", "task", r.taskID, "child", sessionID)
		return title, true
	}

	a.log.Info("子会话认亲开始", "task", r.taskID, "event_session", sessionID, "own_session", r.session)
	start := time.Now()

	ctx, cancel := context.WithTimeout(context.Background(), ownershipTimeout)
	defer cancel()
	d, err := r.api.GetSession(ctx, sessionID)
	if err != nil {
		a.log.Warn("子会话认亲失败：查询会话详情出错，本条审批请求丢弃",
			"task", r.taskID, "event_session", sessionID, "cause", err)
		return "", false
	}
	switch {
	case d.ParentID == r.session:
		r.sessMu.Lock()
		r.childSessions[sessionID] = d.Title
		r.sessMu.Unlock()
		a.log.Info("子会话认亲成功", "task", r.taskID, "child", sessionID,
			"parent", d.ParentID, "title", d.Title, "elapsed_ms", time.Since(start).Milliseconds())
		return d.Title, true
	case d.ParentID == "":
		a.log.Warn("子会话认亲失败：该会话没有父会话，是与本任务无关的顶层会话，本条审批请求丢弃",
			"task", r.taskID, "event_session", sessionID, "own_session", r.session)
	default:
		a.log.Warn("子会话认亲失败：父会话不是本任务会话，opencode「subagent 不可再派生 subagent」"+
			"（task:deny）的不变量可能已被打破，本条审批请求丢弃",
			"task", r.taskID, "event_session", sessionID, "event_parent", d.ParentID, "own_session", r.session)
	}
	return "", false
}

n_opencode_Adapter_resolveIdle.signature:
// resolveIdle 是 idle 去抖到期后的回合分类入口（定时器 goroutine 执行）。
// 代次不匹配说明宽限期内回合又推进了，本次候选作废。
func (a *Adapter) resolveIdle(r *runState, gen uint64, raw json.RawMessage) {
	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	if r.idleGen != gen {
		a.log.Debug("候选回合结束已被新活动撤销", "task", r.taskID,
			"scheduled_gen", gen, "current_gen", r.idleGen)
		return
	}
	a.mapIdle(r, raw)
}

n_opencode_Adapter_scheduleIdle.signature:
// scheduleIdle 把一次 idle 登记为「候选回合结束」，静默满 idleGrace 后才真正分类。
// 调用方须持有 turnMu。
//
// why（去抖而非见 idle 即分类）：idle 是 opencode 的会话状态信号，不等于「模型
// 这一轮说完了」——工具调用间隙、权限等待期间都可能出现瞬时 idle。见 idle 即
// 分类会把半截回合当成完整回合：命中 git 兜底时更会因「仓库里已有新提交」谎报
// completed，协调者据此执行 done，Stop 就在 opencode 仍在干活时杀掉了执行者进程。
//
// 宽限期内任何回合推进（新增文本、非 idle 状态、下一条 idle）都会自增 idleGen，
// 使在途的候选失效——真正的回合结束后不会再有事件，宽限期自然走完。代价是回合
// 分类延迟 idleGrace，相对协调者分钟级的往返可忽略。
func (a *Adapter) scheduleIdle(r *runState, raw json.RawMessage) {
	r.idleGen++
	gen := r.idleGen
	if r.idleTimer != nil {
		r.idleTimer.Stop()
	}
	grace := a.idleGrace
	if grace <= 0 {
		grace = idleGraceDefault
	}

	snapshot := append(json.RawMessage(nil), raw...)
	a.log.Debug("登记候选回合结束，等待去抖", "task", r.taskID, "grace", grace)
	r.idleTimer = time.AfterFunc(grace, func() { a.resolveIdle(r, gen, snapshot) })
}

n_opencode_Adapter_setPartText.signature:
// setPartText 把某个 part 的当前文本置为 text，并把变化反映到 render.log
// 与 progress——part.updated 与 part.delta 两个入口共用。
//
// 追加（新文本是已见文本的延续）时 render.log 只写增量，保持 tail -f 的
// 流式观感；服务端修订该段时写一条带标记的整段，让旁观者知道前面那段已作废
// （render.log 是 append-only 文件，改不了历史）。
func (a *Adapter) setPartText(r *runState, key, text string) {
	old, existed := r.partSeen[key]
	if !existed {
		r.turnOrder = append(r.turnOrder, key)
	}
	if text == old {
		return
	}

	r.idleGen++
	r.partSeen[key] = text
	render := strings.TrimPrefix(text, old)
	if old != "" && !strings.HasPrefix(text, old) {
		render = "\n[以上一段已被服务端修订为]\n" + text
	}
	if err := r.appendRender(render); err != nil {
		a.log.Warn("追加 render.log 失败", "task", r.taskID, "cause", err)
	}

	if old == "" || strings.HasPrefix(text, old) {
		if err := r.frames.Text(key, render); err != nil {
			a.log.Warn("写 text 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
	}
	a.maybeProgress(r)
}

n_opencode_Adapter_watchdog.signature:
// watchdog 是 serve 存活看门狗：周期探活，连续 3 次失败判定 serve 死亡，
// 取消运行 ctx 让订阅退出——failed 结果由 subscribeLoop 统一产出（保持
// 「事件通道只有一个写入者」的关闭权约定）。探活间隔自适应用默认配置
// （见 watchdogConfig）。
func (a *Adapter) watchdog(r *runState) {
	a.watchdogWithConfig(r, watchdogConfig{
		fastInterval:	watchdogFastInterval,
		slowInterval:	watchdogSlowInterval,
		fastProbes:	watchdogFastProbes,
	})
}

n_opencode_Adapter_watchdogWithConfig.signature:
// watchdogWithConfig 是 watchdog 的配置注入骨架（探活节奏自适应逻辑）：
//
//   - 收到新事件（emit 打点 lastEventAt 有变化）→ 回到高频：任务活跃（模型在
//     产出/权限在等裁决），serve 死亡要能被快速发现
//   - 高频下连续 fastProbes 次成功探活且无新事件 → 降频到 slow：任务静默
//     （waiting_review 挂过夜），200ms 高频探活是纯浪费——每天每任务约 43 万次
//     HTTP 请求（P1-17）
//   - 任一失败 → 立即回到高频：死亡判定是看门狗唯一职责，不能被降频拖慢
//     （慢档最坏 3 次 × 2s ≈ 6s 才判死，MVP 可接受）
func (a *Adapter) watchdogWithConfig(r *runState, cfg watchdogConfig) {
	failures := 0
	successes := 0
	prevEvent := r.lastEventAt.Load()
	interval := cfg.fastInterval
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-r.stopCh:
			return
		case <-r.runCtx.Done():
			return
		case <-ticker.C:
			evTs := r.lastEventAt.Load()
			active := evTs != prevEvent
			prevEvent = evTs
			if active && interval != cfg.fastInterval {
				a.log.Debug("探活回到高频：收到新事件，任务活跃", "task", r.taskID)
				successes = 0
				interval = cfg.fastInterval
				ticker.Stop()
				ticker = time.NewTicker(interval)
			}
			if r.handle.Alive() {
				failures = 0
				successes++
				if interval == cfg.fastInterval && !active && successes >= cfg.fastProbes {

					a.log.Debug("探活降频：任务静默，探活间隔升到慢档", "task", r.taskID,
						"fast", cfg.fastInterval, "slow", cfg.slowInterval)
					successes = 0
					interval = cfg.slowInterval
					ticker.Stop()
					ticker = time.NewTicker(interval)
				}
				continue
			}
			failures++
			successes = 0
			if interval != cfg.fastInterval {
				a.log.Debug("探活回到高频：出现失败，需快速判定死亡", "task", r.taskID)
				interval = cfg.fastInterval
				ticker.Stop()
				ticker = time.NewTicker(interval)
			}
			if failures >= watchdogFailThreshold {
				a.log.Error("opencode serve 探活失败达阈值，判定死亡",
					"task", r.taskID, "failures", failures)
				r.runCancel()
				return
			}
		}
	}
}

n_opencode_frameKind.signature:
// frameKind 把 opencode 的 part 类型归类成帧类型。
//
// 为什么 tool 归到 kindSkip：tool part 的**文本增量**是工具入参的流式拼装，
// 不是给人读的内容；工具调用本身由 mapToolPart 以完整的 tool_call 帧上报，
// 在这里再产一路会出现同一次调用两种形态。
//
// 未知类型一律 kindSkip：opencode 上游加了新 part 类型时，宁可少一种帧，
// 也不要把它猜成正文——猜错就是把非正文内容当模型输出展示。
func frameKind(partType string) partFrameKind {
	switch partType {
	case "text":
		return kindText
	case "reasoning":
		return kindReasoning
	default:
		return kindSkip
	}
}

n_opencode_partKey.signature:
// partKey 生成 part 累积对账的键：messageID+partID 唯一标识一个 part
// （真实流中 part id 全局唯一，双 id 是为了对账键可读可查）。
func partKey(msgID, partID string) string {
	return msgID + "\x00" + partID
}

n_opencode_reconcileTurnEnded.signature:
// reconcileTurnEnded 判定取回的会话尾部消息是否真的意味着「回合已结束」。
//
// 为什么不能只靠 CompletedMS：opencode 一个用户回合会产多条 assistant 消息，
// 工具调用各自成条、各自带 completed。只凭「最后一条 assistant 的 CompletedMS
// != 0」会把一条纯工具消息误判成回合终态——executor 死亡/崩溃后会话冻结在
// 工具消息上，补一条假终态会把正常任务主动推进到 waiting_answer，比 B38 原始
// 症状（冻死）更糟。
//
// 判据按行逐条判定、命中即停（真机数据见各行的注释出处）：
//
//	1  CompletedMS == 0                         → 未结束（消息未 finalize：在飞或冻结）
//	2  Finish == "stop"                         → 已结束（自然结束，无 tool part）
//	3  ErrorName == "MessageAbortedError"       → 已结束（会话被 abort 而终）
//	4  ToolStatus == "error"                    → 已结束（工具被拒/报错而终）
//	5  ToolStatus == "completed"                → 未结束（真·回合中途冻结）
//	6  兜底（无 tool、无 error、finish 缺席/其它）→ 已结束（窄兜底，见下）
//
// row2 为什么成立（Finish=="stop" ⇒ 回合结束）：stop 是 opencode 的自然结束标记——
// 模型把话说完、本轮不再有工具调用，消息的 finish 就是 "stop"。实测该形态消息
// 的 parts 为 step-start/text/step-finish（无 tool part），是「回合到此为止」的
// 最直接信号。与实时路径 mapIdle 的判定口径一致（文本完整、无续接意图即分类收尾）。
//
// row4 为什么成立（工具 error ⇒ 回合结束）：本会话 14 条带 state.status=error
// 工具 part 的消息 14/14 后面紧跟的都是 user 消息（或就是会话尾），零反例——
// 「工具报错模型会自己重试、回合不结束」的担心被数据否掉。更重要的代码佐证：
// 实时路径 adapter.go:1236-1241 早就把「回合因权限被拒而终止」当作回合结束并转成
// question 唤醒协调者（rejectedTurnQuestion，adapter.go:482-488）——row4 不是
// 新发明，是让对账口径与实时路径对齐。
//
// row6 为什么是窄兜底且判已结束：真实 payload 里 completed 的消息几乎总带 finish
// （456 条：tool-calls 452 / unknown 2 / 缺席 2，缺席那两条一条是 abort、一条是
// 在飞）。落进 row6 的是 finish="unknown"（本会话 2 条，均为真实回合终态、无 tool
// part）与缺 finish 的经典终态——它们补发是对的。row6 不是主路径，但缺失它会让
// 老版本/异常形态的终态永远补不上，故判已结束。
//
// 返回：回合是否已结束，以及命中的判据行（进日志，供线上判定回溯）。
func reconcileTurnEnded(msg *SessionMessage) (bool, string) {
	if msg.CompletedMS == 0 {
		return false, "unfinalized"
	}
	if msg.Finish == "stop" {
		return true, "stop"
	}
	if msg.ErrorName == "MessageAbortedError" {
		return true, "aborted"
	}
	if msg.ToolStatus == "error" {
		return true, "tool_error"
	}
	if msg.ToolStatus == "completed" {
		return false, "frozen_tool_tail"
	}
	return true, "fallback_terminal"
}

n_opencode_resumeNote.signature:
// resumeNote 拼恢复结果的一句话结论（进 ResumeOutcome.Note 供 manager 转播）。
func resumeNote(mode, sessionID string) string {
	switch mode {
	case executor.ResumeModeReattach:
		return "executor 仍存活，已重连事件流"
	case executor.ResumeModeCold:
		return "已从磁盘载入原会话 " + sessionID + "，上下文完整"
	case executor.ResumeModeFresh:
		return "原会话已不可载入，已新开会话 " + sessionID + "，上下文从下一条指令开始"
	}
	return "已恢复"
}

n_opencode_runState_appendRender.signature:
// appendRender 把消息文本增量追加进 render.log（handoff attach 实况可见）。
//
// 薄封装：实现在 turn 共享包（B2/B3 两个 adapter 同构逻辑），本方法保留
// 调用点已有的 taskDir 上下文（renderPath 由 newRun 按 taskDir 推导）。
func (r *runState) appendRender(delta string) error {
	return turn.AppendRender(r.renderPath, delta)
}

n_opencode_runState_cancelPendingIdle.signature:
// cancelPendingIdle 停掉在途的 idle 去抖定时器并作废候选（自行加锁，
// 供订阅结束等 turnMu 未持有的路径调用）。
func (r *runState) cancelPendingIdle() {
	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	r.idleGen++
	if r.idleTimer != nil {
		r.idleTimer.Stop()
		r.idleTimer = nil
	}
}

n_opencode_runState_clearTurn.signature:
// clearTurn 清空回合累积（回合分类终结时调用）。
//
// partTypes/userMsgs 不清空：它们是会话级事实（part 类型、user 消息 id 全会话
// 唯一），保留才能保证回合边界之后到达的 reasoning 增量与重放的 user 文本 part
// 永不混入下一回合（A-4）。pendingDelta 同样保留：类型未揭晓的暂存增量跨回合
// 边界仍可能被 part.updated 认领。
func (r *runState) clearTurn() {
	r.turnOrder = nil
	r.partSeen = make(map[string]string)
	r.partSnap = make(map[string]bool)
}

n_opencode_runState_closeEvents.signature:
// closeEvents 关闭事件通道（只由 subscribeLoop 的 defer 调用，关闭权唯一）。
// 与 emit 共用 emitMu：置位 evClosed 后任何在途的 emit 都会静默丢弃，
// 保证 idle 定时器 goroutine 的迟到投递不会写已关闭通道。
func (r *runState) closeEvents() {
	r.emitMu.Lock()
	defer r.emitMu.Unlock()
	if r.evClosed {
		return
	}
	r.evClosed = true
	close(r.evCh)
}

n_opencode_runState_subscribeLoop.signature:
// subscribeLoop 是单任务的事件流主循环（唯一持有 evCh 关闭权的 goroutine）：
// 订阅 SSE → mapEvent 逐条映射产出 AdapterEvent；订阅退出后按退出原因
// （serve 死亡 / 流不可恢复）产出 failed 结果，随后关闭事件通道。
func (r *runState) subscribeLoop(a *Adapter) {
	defer func() {

		r.cancelPendingIdle()
		r.closeOnce.Do(r.closeEvents)

		select {
		case <-r.stopCh:
		default:
			a.drop(r.taskID)
		}
		a.log.Info("opencode 事件流订阅退出", "task", r.taskID)
	}()
	err := r.api.SubscribeEvents(r.runCtx, func(raw json.RawMessage) {
		a.mapEvent(r, raw)
	}, func() {

		a.log.Warn("SSE 断连已恢复：断连间隙的权限请求可能丢失（/event 无重放语义），正在重问未决项，"+
			"若任务仍卡在等待决策请 handoff attach 查看或 handoff resume --force 收口",
			"task", r.taskID, "session", r.session)
		go a.reconcileAfterRecovery(context.Background(), r.taskID, "reconnect")
		go a.rediscoverPendingPermissions(context.Background(), r.taskID)
	})
	select {
	case <-r.stopCh:
		return
	default:
	}
	if !r.handle.Alive() {

		tail := turn.TailRunes(r.handle.LogTail(), 200)
		a.log.Error("opencode serve 已退出", "task", r.taskID, "stderr_tail", tail)
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	false, SessionID: r.session,
			FailReason:	"opencode serve 已退出: " + tail,
		}})

		if kerr := r.handle.Kill(); kerr != nil {
			a.log.Warn("serve 死亡后回收执行者进程失败", "task", r.taskID, "cause", kerr)
		}
		return
	}
	a.log.Warn("opencode 事件流意外中断，按失败结束回合", "task", r.taskID, "cause", err)
	a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
		OK:	false, SessionID: r.session,
		FailReason:	"opencode 事件流意外中断: " + turn.TailRunes(fmt.Sprint(err), 200),
	}})
}

