n_opencode_runState_turnText.signature:
// turnText 按 part 首见顺序拼出当前回合的完整文本。
//
// 为什么不维护一个累加字符串：服务端会修订同一 part 的快照，累加字符串没法
// 撤销已写入的旧值（A-6）；按 part 存当前值再拼接，修订天然是覆盖。
func (r *runState) turnText() string {
	var b strings.Builder
	for _, key := range r.turnOrder {
		b.WriteString(r.partSeen[key])
	}
	return b.String()
}

n_opencode_toolDetail.signature:
// toolDetail 从工具入参里取一句给人看的凭据（进 TimingEntry.Detail）。
//
// 优先 input.command（命令类工具），没有就用整个 input 的紧凑 JSON。
// 截断由 Segmenter 按 DetailRunes 负责，这里不截——两处都截会截两次。
func toolDetail(input json.RawMessage) string {
	var in struct {
		Command string `json:"command"`
	}
	if len(input) > 0 && json.Unmarshal(input, &in) == nil && in.Command != "" {
		return in.Command
	}
	return string(input)
}

n_opencode_toolInputReady.signature:
// toolInputReady 判断 state.input 是否已经带有实际入参。
// opencode 的 pending 事件稳定地带空对象；空对象不是有效凭据，不能据此写死
// tool_call 帧或 TimingEntry.Detail。state.input 契约上是对象，非对象值保守地视为
// 已有内容，终态回落由 mapToolPart 的 terminal 分支负责。
func toolInputReady(input json.RawMessage) bool {
	var fields map[string]json.RawMessage
	if json.Unmarshal(input, &fields) == nil {
		return len(fields) > 0
	}
	trimmed := strings.TrimSpace(string(input))
	return trimmed != "" && trimmed != "null"
}

n_opencode_toolPartKey.signature:
// toolPartKey 取工具调用的配对键：优先 callID，缺失时回落 part.id。
//
// 为什么优先 callID：permission.asked 事件里的 tool.callID 用的就是它
// （testdata/spike5-events.jsonl 第 289 行），拿同一个键才对得上审批与调用。
func toolPartKey(callID, partID string) string {
	if callID != "" {
		return callID
	}
	return partID
}

n_opencode_toolResultStatus.signature:
// toolResultStatus 把 opencode 的工具状态映射成帧上的 status。
//
// 返回 ok=false 表示**不是终态**（pending/running/未知）：不产 tool_result 帧、
// 不收工具段。error 是真实存在的终态——权限被拒会终结回合并只留 error 状态的
// tool part（见 mapIdle 的注释）。
//
// 不认识的状态一律按非终态处置，理由的不对称性与 grok 版一致：把非终态当终态
// 会提前收段并留下一个永远配不上的 start；把终态当非终态只是少一条条目，
// 由聚合层的 Partial 如实标出。
func toolResultStatus(status string) (string, bool) {
	switch status {
	case "completed":
		return "ok", true
	case "error":
		return "error", true
	default:
		return "", false
	}
}
